    //#endregion 🔖️FormKit

    //#region 🔖️Terminology
    // 🗣️ Shared two-axis (locale × terminology) label resolution — replaces the ~25x hand-rolled
    // `struct XLabels { .. }` + `const X_LABELS_EN/DE` + `fn x_labels(view_state) -> &'static XLabels`
    // pattern duplicated per app, AND the 4-crate hand-rolled `NATIVE_EN/NATIVE_DE/REUSE_EN/REUSE_DE` +
    // non-exhaustive `match (terminology, is_de) { ..., (_, true) => ... }` terminology resolvers this
    // SDK never covered. `app_labels!` now declares all four cells per field and resolves them via an
    // exhaustive match on the generated `Locale`/`Terminology` enums — no catch-all arm is possible, so
    // adding a locale or terminology to `🔣️ui-axes.json` breaks every invocation until it supplies that
    // cell. See ticket 26/08/03/COMPILE-TIME-CHECKED-UI-LABELS-ACROSS-LOCALE-TERMINOLOGY-AND-BRAND.

    pub use ui_wgpu::wgpu::AppLabels;

    /// 🗣️ Anything `resolve_labels` can resolve a label set from — `ViewModel` (locale+terminology
    /// from the shell) and, since the B1 config-driven apps stopped threading `ViewModel` through
    /// render, any per-app `Config` exposing just a raw `cfg.locale` string (region-tolerant: `"de"`
    /// and `"de-DE"` both resolve to `Locale::De`, matching every hand-rolled `is_de_locale` this
    /// replaces) — `terminology()` defaults to `Native`, matching every one of those apps' behavior
    /// (none of them threaded a terminology axis themselves).
    pub trait LabelAxes {
        fn locale(&self) -> Locale;
        fn terminology(&self) -> Terminology {
            Terminology::Native
        }
    }

    impl LabelAxes for ViewModel {
        fn locale(&self) -> Locale {
            self.locale
        }
        fn terminology(&self) -> Terminology {
            self.terminology
        }
    }

    /// 🗣️ Region-tolerant `"de"`/`"de-DE"` → `Locale::De` parse, `_` → `Locale::En` — the shared body
    /// of every hand-rolled per-app `is_de_locale`/`fn locale(cfg) -> Locale` this replaces.
    pub fn locale_from_str(locale: &str) -> Locale {
        if locale.starts_with("de") {
            Locale::De
        } else {
            Locale::En
        }
    }

    /// 🗣️ Resolves the active label set for the shell-provided locale/terminology axes.
    pub fn resolve_labels<L: AppLabels>(axes: &impl LabelAxes) -> &'static L {
        L::labels(axes.locale(), axes.terminology())
    }

    /// 🗣️ Config-driven counterpart of `resolve_labels` for the B1 apps whose `Config` type lives
    /// outside their `_ui` crate (the orphan rule blocks `impl LabelAxes for` a foreign `Config` from
    /// `_ui`) — call as `resolve_labels_for_locale::<XLabels>(&cfg.locale)`. Always resolves
    /// `Terminology::Native`, matching every one of those apps' pre-existing behavior.
    pub fn resolve_labels_for_locale<L: AppLabels>(locale: &str) -> &'static L {
        L::labels(locale_from_str(locale), Terminology::Native)
    }

    /// 🗣️ Declares a two-axis label struct plus its four `NATIVE_EN`/`NATIVE_DE`/`REUSE_EN`/`REUSE_DE`
    /// consts and `AppLabels` impl in one compact block — resolve the active set with
    /// `resolve_labels::<XLabels>(view_state)`. Every field requires all four cells explicitly (no
    /// implicit "reuse falls back to native") so a plugin's terminology coverage is always visible at
    /// the declaration site, not inferred.
    ///
    /// ```ignore
    /// semio_framework_plugin::app_labels! {
    ///     struct Puzzle3dLabels {
    ///         object: native_en "Object", native_de "Objekt", reuse_en "Component", reuse_de "Bestandskomponente";
    ///         lod: native_en "LOD", native_de "LOD", reuse_en "LOD", reuse_de "LOD";
    ///     }
    /// }
    /// ```
    #[macro_export]
    macro_rules! app_labels {
    (
        $(#[$meta:meta])*
        $vis:vis struct $Name:ident {
            $( $field:ident: native_en $nen:expr, native_de $nde:expr, reuse_en $ren:expr, reuse_de $rde:expr );+ $(;)?
        }
    ) => {
        $(#[$meta])*
        $vis struct $Name {
            $( $vis $field: $crate::LabelText ),+
        }

        impl $Name {
            // 🌐️ PROCESS-PLUGIN-MIGRATION-TO-CRATE-AND-TAXONOMY-CONSOLIDATION: these carry the
            // struct's own `$vis` (was hardcoded private) — once a plugin's taxonomy splits its
            // `app_labels!` struct into its own `🦀️terminology.rs`, sibling `🎮️commands/*`/
            // `🪟️windows/*` test modules need `Labels::NATIVE_EN` etc. directly (mirrors how flow's
            // pilot never hit this because it never referenced the const cross-module). Additive:
            // only widens visibility, never narrows it, so every existing `app_labels!` caller is
            // unaffected.
            $vis const NATIVE_EN: Self = Self { $( $field: $crate::LabelText::__from_app_labels($nen) ),+ };
            $vis const NATIVE_DE: Self = Self { $( $field: $crate::LabelText::__from_app_labels($nde) ),+ };
            $vis const REUSE_EN: Self = Self { $( $field: $crate::LabelText::__from_app_labels($ren) ),+ };
            $vis const REUSE_DE: Self = Self { $( $field: $crate::LabelText::__from_app_labels($rde) ),+ };
        }

        impl $crate::AppLabels for $Name {
            fn labels(locale: $crate::Locale, terminology: $crate::Terminology) -> &'static Self {
                match (terminology, locale) {
                    ($crate::Terminology::Native, $crate::Locale::En) => &Self::NATIVE_EN,
                    ($crate::Terminology::Native, $crate::Locale::De) => &Self::NATIVE_DE,
                    ($crate::Terminology::Reuse, $crate::Locale::En) => &Self::REUSE_EN,
                    ($crate::Terminology::Reuse, $crate::Locale::De) => &Self::REUSE_DE,
                }
            }
        }
    };
}

    #[cfg(test)]
    mod terminology_tests {
        use super::*;

        app_labels! {
            struct SampleLabels {
                greeting: native_en "Hello", native_de "Hallo", reuse_en "Hi", reuse_de "Servus";
            }
        }

        #[semio_framework_async_macros::async_test]
        async fn resolve_labels_is_exhaustive_over_all_four_cells() {
            let native_en = ViewModel { locale: Locale::En, terminology: Terminology::Native, ..ViewModel::default() };
            let native_de = ViewModel { locale: Locale::De, terminology: Terminology::Native, ..ViewModel::default() };
            let reuse_en = ViewModel { locale: Locale::En, terminology: Terminology::Reuse, ..ViewModel::default() };
            let reuse_de = ViewModel { locale: Locale::De, terminology: Terminology::Reuse, ..ViewModel::default() };
            assert_eq!(resolve_labels::<SampleLabels>(&native_en).greeting.as_str(), "Hello");
            assert_eq!(resolve_labels::<SampleLabels>(&native_de).greeting.as_str(), "Hallo");
            assert_eq!(resolve_labels::<SampleLabels>(&reuse_en).greeting.as_str(), "Hi");
            assert_eq!(resolve_labels::<SampleLabels>(&reuse_de).greeting.as_str(), "Servus");
        }
    }
    //#endregion 🔖️Terminology

    //#region 🔖️ActionFactory
    // 🎯️ Shared ~30x hand-rolled `fn x_action(action: &str, args: Option<Value>) -> ActionDescriptor {
    // ActionDescriptor { controller_id: X_CONTROLLER_ID.into(), action: action.into(), args:
    // optional_json_to_dsl(args) } }` body — every app keeps its own locally-named wrapper (so call
    // sites never change), delegating to `ActionFactory::new(X_CONTROLLER_ID).action(action, args)`.

    pub const UI_COMMAND_VALUE_DEPTH: usize = 64;
    pub const UI_COMMAND_VALUE_ITEMS: usize = 256;

    enum UiCommandJsonFrame {
        List { cursor: ui::UiListCursor, output: Vec<Value> },
        Map { cursor: ui::UiMapCursor, output: serde_json::Map<String, Value>, key: Option<String> },
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum UiCommandJsonStep {
        MoreWork,
        Ready,
        Cancelled,
        Fault,
    }

    struct UiCommandJsonProducer {
        stack: UiFixedList<UiCommandJsonFrame, UI_COMMAND_VALUE_DEPTH>,
        pending: Option<UiValue>,
        ready: Option<Value>,
        fault: Option<Fault>,
        items: usize,
    }

    impl UiCommandJsonProducer {
        fn try_new(value: &UiValue) -> Result<Self, Fault> {
            let pending = value.credited_clone().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("app.intent.bridge-admission"), "typed intent value alias admission refused before conversion"))?;
            Ok(Self { stack: UiFixedList::default(), pending: Some(pending), ready: None, fault: None, items: 0 })
        }

        fn reject(&mut self, code: &'static str, detail: &'static str) -> UiCommandJsonStep {
            self.pending = None;
            self.stack = UiFixedList::default();
            self.fault = Some(Fault::new(FaultOrigin::Framework, FaultCode::new(code), detail));
            UiCommandJsonStep::Fault
        }

        fn accept(&mut self, value: Value) -> UiCommandJsonStep {
            let Some(items) = self.items.checked_add(1).filter(|items| *items <= UI_COMMAND_VALUE_ITEMS) else {
                return self.reject("app.intent.bridge-items", "typed intent value exceeds the fixed command item census");
            };
            self.items = items;
            let Some(frame) = self.stack.last_mut() else {
                self.ready = Some(value);
                return UiCommandJsonStep::Ready;
            };
            match frame {
                UiCommandJsonFrame::List { output, .. } => {
                    if output.try_reserve(1).is_err() {
                        return self.reject("app.intent.bridge-allocation", "typed intent list candidate allocation was refused");
                    }
                    output.push(value);
                }
                UiCommandJsonFrame::Map { output, key, .. } => {
                    let Some(key) = key.take() else {
                        return self.reject("app.intent.bridge-map-key", "typed intent map child lost its retained key");
                    };
                    output.insert(key, value);
                }
            }
            UiCommandJsonStep::MoreWork
        }

        fn drive_one(&mut self, cancelled: bool, deadline_expired: bool) -> UiCommandJsonStep {
            if self.ready.is_some() {
                return UiCommandJsonStep::Ready;
            }
            if self.fault.is_some() {
                return UiCommandJsonStep::Fault;
            }
            if cancelled {
                self.pending = None;
                self.stack = UiFixedList::default();
                self.fault = Some(Fault::new(FaultOrigin::Framework, FaultCode::new("app.intent.bridge-cancelled"), "typed intent value conversion was cancelled"));
                return UiCommandJsonStep::Cancelled;
            }
            if deadline_expired {
                return UiCommandJsonStep::MoreWork;
            }
            if let Some(value) = self.pending.take() {
                return match value {
                    UiValue::Null => self.accept(Value::Null),
                    UiValue::Bool(value) => self.accept(Value::Bool(value)),
                    UiValue::Number(value) => self.accept(serde_json::Number::from_f64(value).map(Value::Number).unwrap_or(Value::Null)),
                    UiValue::Text(value) => self.accept(Value::String(value.to_string())),
                    UiValue::List(values) => {
                        let frame = UiCommandJsonFrame::List { cursor: values.cursor(), output: Vec::new() };
                        match self.stack.try_push(frame) {
                            Ok(()) => UiCommandJsonStep::MoreWork,
                            Err(_) => self.reject("app.intent.bridge-depth", "typed intent list exceeds the fixed command depth"),
                        }
                    }
                    UiValue::Map(values) => {
                        let frame = UiCommandJsonFrame::Map { cursor: values.cursor(), output: serde_json::Map::new(), key: None };
                        match self.stack.try_push(frame) {
                            Ok(()) => UiCommandJsonStep::MoreWork,
                            Err(_) => self.reject("app.intent.bridge-depth", "typed intent map exceeds the fixed command depth"),
                        }
                    }
                };
            }
            let Some(frame) = self.stack.last_mut() else {
                return self.reject("app.intent.bridge-state", "typed intent conversion lost its retained frame");
            };
            let completed = match frame {
                UiCommandJsonFrame::List { cursor, output } => match cursor.next() {
                    Some(value) => {
                        self.pending = Some(value);
                        return UiCommandJsonStep::MoreWork;
                    }
                    None => Value::Array(std::mem::take(output)),
                },
                UiCommandJsonFrame::Map { cursor, output, key } => match cursor.next() {
                    Some((next_key, value)) => {
                        *key = Some(next_key.to_string());
                        self.pending = Some(value);
                        return UiCommandJsonStep::MoreWork;
                    }
                    None => Value::Object(std::mem::take(output)),
                },
            };
            let _ = self.stack.pop();
            self.accept(completed)
        }

        fn take_ready(mut self) -> Result<Value, Self> {
            self.ready.take().ok_or(self)
        }

        fn take_fault(&mut self) -> Option<Fault> {
            self.fault.take()
        }
    }

    async fn ui_value_to_json_retained(value: &UiValue) -> Result<Value, Fault> {
        let mut producer = UiCommandJsonProducer::try_new(value)?;
        loop {
            match producer.drive_one(false, false) {
                UiCommandJsonStep::MoreWork => semio_framework_async::yield_once().await,
                UiCommandJsonStep::Ready => return producer.take_ready().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("app.intent.bridge-publication"), "typed intent candidate was not complete")),
                UiCommandJsonStep::Cancelled | UiCommandJsonStep::Fault => {
                    return Err(producer.take_fault().unwrap_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("app.intent.bridge-fault"), "typed intent conversion faulted")));
                }
            }
        }
    }

    /// 🔀️ M1: advances a firing `ActionBinding`'s echoed `args` and trigger `input` through
    /// retained fixed-depth cursors into one complete typed-command JSON candidate.
    /// `serde_json::Value` for `ArtifactApp::command_from_action`'s `Option<&Value>` — `input` wins on
    /// key collision when both are JSON objects (the trigger-specific payload is the more specific,
    /// more recent datum); otherwise a present `input` replaces `args` wholesale (a scalar `input`,
    /// e.g. `Trigger::Delta`'s signed step count, has no field to merge INTO). `None` when neither is
    /// set, matching `command_from_action`'s existing `None` (no-args) call shape.
    // 🚫️async: E1-adjacent pure structural transform consumed by typed intent dispatch.
    async fn merge_ui_values(args: Option<&UiValue>, input: Option<&UiValue>) -> Result<Option<Value>, Fault> {
        let args = match args {
            Some(value) => Some(ui_value_to_json_retained(value).await?),
            None => None,
        };
        let input = match input {
            Some(value) => Some(ui_value_to_json_retained(value).await?),
            None => None,
        };
        Ok(match (args, input) {
            (None, None) => None,
            (Some(args), None) => Some(args),
            (None, Some(input)) => Some(input),
            (Some(Value::Object(mut args)), Some(Value::Object(input))) => {
                args.extend(input);
                Some(Value::Object(args))
            }
            (Some(_), Some(input)) => Some(input),
        })
    }

    /// 🎯️ Constructs [`ActionId`]s bound to one controller id (renamed `scope`, per
    /// `📓️recipe-plugin.md` §1's direct `ActionId::v1(scope, name)` mapping). ⚠️ Decision: the old
    /// `ActionDescriptor` bundled a controller-scoped id AND its optional args into one value a caller
    /// assigned straight to a node's sole `action` field; the new model splits "what to call"
    /// (`ActionId`) from "when" (`Trigger`, chosen wherever `.on`/`.on_with` is actually called on a
    /// node builder) — a factory scoped only to one controller cannot know the trigger, so trigger
    /// selection stays out of scope here too. `args` is still accepted and converted
    /// (`UiValue`), just returned alongside the id rather than folded into one struct — call
    /// `.on_with(trigger, id, args)` when `args.is_some()`, `.on(trigger, id)` otherwise.
    pub struct ActionFactory {
        controller_id: &'static str,
    }

    impl ActionFactory {
        pub const fn new(controller_id: &'static str) -> Self {
            Self { controller_id }
        }

        pub fn action(&self, action: &str, args: Option<UiValue>) -> UiAssemblyResult<(ActionId, Option<UiValue>)> {
            let id = ActionId::try_v1(self.controller_id, action).ok_or_else(|| ui_assembly_error("action-factory.id"))?;
            Ok((id, args))
        }
    }
    //#endregion 🔖️ActionFactory

    //#region 🧪️MergeUiValuesTests
    /// 🎯️ M1 retained typed-command bridge fixtures, kept separate from intent dispatch so
    /// cursor, cancellation, deadline, and depth regressions fail at their owner boundary.
    #[cfg(test)]
    mod merge_ui_values_tests {
        use super::*;

        fn ui_text(value: &str) -> ui::UiText {
            ui::UiText::try_from_str(value).expect("bounded fixture text")
        }

        fn ui_list(values: impl IntoIterator<Item = UiValue>) -> ui::UiList {
            let mut builder = ui::UiListBuilder::try_new().expect("fixed list builder");
            for value in values {
                builder.push(value).expect("fixed list page");
            }
            builder.finish()
        }

        fn ui_map(entries: impl IntoIterator<Item = (String, UiValue)>) -> ui::UiMap {
            let mut builder = ui::UiMapBuilder::try_new().expect("fixed map builder");
            for (key, value) in entries {
                builder.push(key, value).expect("ascending fixed map page");
            }
            builder.finish()
        }

        #[semio_framework_async_macros::async_test]
        async fn retained_ui_value_bridge_advances_every_shape_to_the_matching_json_candidate() {
            assert_eq!(ui_value_to_json_retained(&UiValue::Null).await.expect("retained null"), Value::Null);
            assert_eq!(ui_value_to_json_retained(&UiValue::Bool(true)).await.expect("retained bool"), Value::Bool(true));
            assert_eq!(ui_value_to_json_retained(&UiValue::Number(-2.5)).await.expect("retained number"), serde_json::json!(-2.5));
            assert_eq!(ui_value_to_json_retained(&UiValue::Text(ui_text("hi"))).await.expect("retained text"), Value::String("hi".into()));
            assert_eq!(ui_value_to_json_retained(&UiValue::List(ui_list([UiValue::Number(1.0), UiValue::Bool(false)]))).await.expect("retained list"), serde_json::json!([1.0, false]));
            let mut map = std::collections::BTreeMap::new();
            map.insert("id".to_string(), UiValue::Text(ui_text("w1")));
            assert_eq!(ui_value_to_json_retained(&UiValue::Map(ui_map(map))).await.expect("retained map"), serde_json::json!({ "id": "w1" }));
        }

        #[semio_framework_async_macros::async_test]
        async fn merge_ui_values_returns_none_when_neither_side_is_set() {
            assert_eq!(merge_ui_values(None, None).await.expect("empty merge"), None);
        }

        #[semio_framework_async_macros::async_test]
        async fn merge_ui_values_falls_back_to_whichever_single_side_is_set() {
            assert_eq!(merge_ui_values(Some(&UiValue::Text(ui_text("a"))), None).await.expect("args merge"), Some(serde_json::json!("a")));
            assert_eq!(merge_ui_values(None, Some(&UiValue::Number(3.0))).await.expect("input merge"), Some(serde_json::json!(3.0)));
        }

        /// 🔀️ The decided merge rule: `input` wins on key collision when both are objects.
        #[semio_framework_async_macros::async_test]
        async fn merge_ui_values_prefers_input_on_key_collision_between_two_maps() {
            let mut args_map = std::collections::BTreeMap::new();
            args_map.insert("value".to_string(), UiValue::Number(1.0));
            args_map.insert("scope".to_string(), UiValue::Text(ui_text("keep")));
            let mut input_map = std::collections::BTreeMap::new();
            input_map.insert("value".to_string(), UiValue::Number(2.0));
            let merged = merge_ui_values(Some(&UiValue::Map(ui_map(args_map))), Some(&UiValue::Map(ui_map(input_map)))).await.expect("retained merge").expect("both sides set");
            assert_eq!(merged, serde_json::json!({ "value": 2.0, "scope": "keep" }));
        }

        /// 🔀️ A scalar `input` has no field to merge INTO — it replaces `args` wholesale (e.g.
        /// `Trigger::Delta`'s signed step count next to a non-object `args`).
        #[semio_framework_async_macros::async_test]
        async fn merge_ui_values_replaces_a_non_object_args_wholesale_when_input_is_also_set() {
            let merged = merge_ui_values(Some(&UiValue::Text(ui_text("stale"))), Some(&UiValue::Number(-2.0))).await.expect("retained merge");
            assert_eq!(merged, Some(serde_json::json!(-2.0)));
        }

        #[test]
        fn retained_ui_value_bridge_cancel_and_deadline_preserve_the_original_owner() {
            let original = UiValue::List(ui_list([UiValue::Text(ui_text("kept"))]));
            let mut producer = UiCommandJsonProducer::try_new(&original).expect("credited alias");
            assert_eq!(producer.drive_one(false, true), UiCommandJsonStep::MoreWork);
            assert_eq!(producer.items, 0);
            assert_eq!(producer.drive_one(true, false), UiCommandJsonStep::Cancelled);
            let UiValue::List(values) = original else { panic!("original list") };
            assert_eq!(values.len(), 1);
        }

        #[test]
        fn retained_ui_value_bridge_rejects_depth_plus_one_without_consuming_the_original() {
            let mut original = UiValue::Null;
            for _ in 0..=UI_COMMAND_VALUE_DEPTH {
                original = UiValue::List(ui_list([original]));
            }
            let mut producer = UiCommandJsonProducer::try_new(&original).expect("credited root alias");
            let mut opportunities = 0;
            loop {
                opportunities += 1;
                match producer.drive_one(false, false) {
                    UiCommandJsonStep::MoreWork => continue,
                    UiCommandJsonStep::Fault => break,
                    step => panic!("unexpected bridge step {step:?}"),
                }
            }
            assert!(opportunities > UI_COMMAND_VALUE_DEPTH);
            let UiValue::List(values) = original else { panic!("original list") };
            assert_eq!(values.len(), 1);
        }
    }
    //#endregion 🧪️MergeUiValuesTests

    #[cfg(test)]
    #[path = "🧪️tests/🧬️mutation-fixtures/🦀️.rs"]
    pub(crate) mod mutation_fixture;

    //#region 🔖️Testkit
    pub mod testkit {
        //! 🧪️ Generic test-harness helpers for `ArtifactApp` implementors. Factors out the ~24x duplicated
        //! `meta()`/`new_app()`/`new_app_with_registry()`/`paired_apps()` boilerplate plus the repeated
        //! undo-redo / two-instance-convergence / ingest-idempotency test *bodies* (parameterized by closures
        //! for the app-specific action names/snapshot shape, so only the control flow is shared). Not
        //! `#[cfg(test)]` — apps' own `#[cfg(test)]` modules call these as a regular dependency; see
        //! `terminology_tests`/`panel_kit_tests` above for the sibling pattern of testing SDK primitives
        //! themselves inline.

        use super::{register_framework_reserved_factories, ActionMeta, App, AppActionRegistry, ArtifactApp, ArtifactToolFactoryRegistry, PluginApp, VcsArtifactApp};
        use store::{Backbone, BackboneMessage, MemoryBackbone};

        /// 🧪️ Mounts the production shared reserved-action factories on an isolated harness bus.
        pub fn register_framework_reserved_action_factories<A: ArtifactApp>(bus: &semio_framework::ActionBus, controller_id: &str) -> Result<(), super::Fault> {
            let mut registry = ArtifactToolFactoryRegistry::<A>::new(bus, controller_id);
            register_framework_reserved_factories(&mut registry)
        }

        /// 🪪️ A local-actor `ActionMeta` for test dispatch (`instance_id: 1`).
        // 🚫️async: E1 pure constructor, called pervasively as `&meta("...")` — see R9.
        pub fn meta(actor: &str) -> ActionMeta {
            ActionMeta { actor: actor.into(), instance_id: 1 }
        }

        // 🏛️ 👁️✏️ W3 dissolution (ticket 26/08/16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET): the two-
        // generations-obsolete `assert_constitutional_crates`/`assert_taxonomy_components` gate (ticket
        // 26/07/29/MOVE-APPS-INTO-S-PRODUCT-TREE-WITH-CONSTITUTIONAL-CRATES) hunted for a literal
        // `🎛️apps/` directory next to a plugin's manifest dir and hard-`panic!`ked when none was found.
        // Repo-wide grep confirmed zero callers (not even `Plugin::builder`, despite its own docstring's
        // stale claim) — dead code whose ONE reachable branch would now panic unconditionally, since
        // `🎛️apps` can never exist again. Deleted rather than retargeted: the shape it enforced (an
        // app-root ⚙️engine, `constitutional-crate` slots) is itself retired by the ENGINELESS ticket and
        // by this ticket's surface dissolution, and the same completeness duty is covered live by the
        // TS-side `validateTaxonomyTree` (📇️registry/📜️script.ts) and `policyTaxonomyDirsBreaches` (root
        // 📜️script.ts), both already surface-aware.

        /// 🧬️ A registry-less wrapper (`VcsArtifactApp::new`) for store-only tests. UI and typed
        /// command dispatch fail closed until a real registry and exact factory are supplied.
        pub async fn new_app<A: ArtifactApp + Default>() -> VcsArtifactApp<A> {
            VcsArtifactApp::new(A::default()).await
        }

        /// 🧬️ A registry-backed wrapper carrying `manifest`'s real `AppActionRegistry` — needed whenever a
        /// test must exercise declared-arg defaults/required-arg enforcement or View/Shell kind discipline.
        pub async fn new_app_with_registry<A: ArtifactApp + Default>(manifest: fn() -> App) -> VcsArtifactApp<A> {
            let definition = manifest().definition;
            VcsArtifactApp::with_registry(A::default(), AppActionRegistry::from_definition(&definition)).await
        }

        /// 🧬️ A registry-backed wrapper whose manifest is authored asynchronously by the concrete fixture.
        pub async fn new_registered_app<A, Manifest>(manifest: Manifest) -> VcsArtifactApp<A>
        where
            A: ArtifactApp + Default,
            Manifest: std::future::Future<Output = App>,
        {
            let definition = manifest.await.definition;
            VcsArtifactApp::with_registry(A::default(), AppActionRegistry::from_definition(&definition)).await
        }

        /// 🧹️ Closes one registered fixture through the exact retained app close state machine.
        pub fn close_registered_fixture_app<A: ArtifactApp>(app: &mut VcsArtifactApp<A>) {
            for _ in 0..64 {
                if app.close_terminal_is_empty() { return; }
                match app.close_step(1, store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES).expect("registered fixture close") {
                    super::PluginCloseStep::Pending { released_items, released_bytes } => assert!(released_items <= 1 && released_bytes <= store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES),
                    super::PluginCloseStep::Blocked { reason } => panic!("registered fixture close blocked: {reason}"),
                    super::PluginCloseStep::Complete => break,
                }
            }
            assert!(app.close_terminal_is_empty(), "registered fixture did not reach its exact terminal-empty witness");
        }

        /// 🔗️ Two registry-less store-only instances joined by an in-memory backbone on `channel`.
        pub async fn paired_apps<A: ArtifactApp + Default>(channel: &str) -> (VcsArtifactApp<A>, VcsArtifactApp<A>) {
            let mut a = new_app::<A>().await;
            let mut b = new_app::<A>().await;
            let (backbone_a, backbone_b) = MemoryBackbone::pair(channel, channel).await;
            a.attach_backbone(store::Backbones::Memory(backbone_a)).await.expect("attach a");
            b.attach_backbone(store::Backbones::Memory(backbone_b)).await.expect("attach b");
            (a, b)
        }

        /// 🧬️ Two explicitly registered fixture instances joined by an in-memory backbone.
        pub async fn paired_registered_apps<A, Manifest, Build>(channel: &str, manifest: Build) -> (VcsArtifactApp<A>, VcsArtifactApp<A>)
        where
            A: ArtifactApp + Default,
            Manifest: std::future::Future<Output = App>,
            Build: Fn() -> Manifest,
        {
            let mut a = new_registered_app::<A, _>(manifest()).await;
            let mut b = new_registered_app::<A, _>(manifest()).await;
            let (backbone_a, backbone_b) = MemoryBackbone::pair(channel, channel).await;
            a.attach_backbone(store::Backbones::Memory(backbone_a)).await.expect("attach a");
            b.attach_backbone(store::Backbones::Memory(backbone_b)).await.expect("attach b");
            (a, b)
        }

        /// 🧪️ Runs `command` once via the typed channel, asserts `probe(app)` matches `after`, undoes (still
        /// the framework-reserved `"undo"` action) and asserts `before`, redoes and asserts `after` again — the
        /// repeated undo/redo round-trip test body. B1: takes a typed `A::Command` value (`dispatch_typed`) —
        /// `ArtifactApp::handle_action`'s stringly-typed dispatch no longer exists.
        pub async fn assert_undo_redo_round_trip<A, P>(app: &mut VcsArtifactApp<A>, command: A::Command, probe: impl Fn(&VcsArtifactApp<A>) -> P, before: P, after: P)
        where
            A: ArtifactApp,
            P: PartialEq + std::fmt::Debug,
        {
            app.dispatch_typed(command, &meta("local")).await.expect("apply command");
            assert_eq!(probe(app), after, "command did not produce the expected snapshot");
            app.handle_action("undo", None, &meta("local")).await.expect("undo");
            assert_eq!(probe(app), before, "undo did not revert to the expected snapshot");
            app.handle_action("redo", None, &meta("local")).await.expect("redo");
            assert_eq!(probe(app), after, "redo did not reapply the expected snapshot");
        }

        /// 🧪️ Every declared app action must bridge through `command_from_action` and round-trip `command_id`.
        pub async fn assert_declared_actions_bridge_to_commands<A: ArtifactApp + Default>(manifest: fn() -> App) {
            use semio_framework::{effective_action_args, DslValue};
            use store::pack_rt::dsl_value_to_json;
            let definition = manifest().definition;
            let _app = A::default();
            let skip = [
                "undo",
                "redo",
                "commitCheckpoint",
                "createAlternative",
                "switchAlternative",
                "checkoutCheckpoint",
                "copy",
                "cut",
                "paste",
                "revertToCommand",
                "setHistoryCommandFilter",
                "noteShellCommand",
                "recordTutorial",
                "startIntroduction",
                "startTutorial",
                "setActiveUtility",
                "setActiveTool",
                "interactionSelect",
                "interactionHover",
                "clearSelection",
                "selectAll",
                "setSelectionMode",
                "setInteractionGranularity",
            ];
            for action in definition.window_kinds.iter().flat_map(|window| &window.actions) {
                if skip.contains(&action.id.as_str()) {
                    continue;
                }
                let empty_args = DslValue::Object(Vec::new());
                let staged = effective_action_args(&action.args, &empty_args, None);
                let args_json = dsl_value_to_json(staged);
                let command = A::command_from_action(&action.id, Some(&args_json)).await.unwrap_or_else(|error| panic!("action {} failed to bridge: {}", action.id, error.message));
                assert_eq!(A::command_id(&command).await, action.id.as_str(), "command_id mismatch for action {}", action.id);
            }
        }

        /// 🧪️ `command_a`/`command_b` are applied to two `paired_apps` instances, a neutral history action
        /// (`commitCheckpoint`) pumps each side's inbound operations, then `probe` must agree on both — the repeated
        /// two-instance-convergence test body (see `playbook-plugin`'s
        /// `two_instances_converge_disjoint_edits_via_backbone` for the original, app-specific version).
        pub async fn assert_two_instances_converge<A, P>(channel: &str, command_a: A::Command, command_b: A::Command, probe: impl Fn(&VcsArtifactApp<A>) -> P)
        where
            A: ArtifactApp + Default,
            P: PartialEq + std::fmt::Debug,
        {
            let (mut instance_a, mut instance_b) = paired_apps::<A>(channel).await;
            instance_a.dispatch_typed(command_a, &meta("actor-a")).await.expect("a applies its edit");
            instance_b.dispatch_typed(command_b, &meta("actor-b")).await.expect("b applies its edit");
            instance_a.handle_action("commitCheckpoint", None, &meta("actor-a")).await.expect("pump a");
            instance_b.handle_action("commitCheckpoint", None, &meta("actor-b")).await.expect("pump b");
            assert_eq!(probe(&instance_a), probe(&instance_b), "both instances must converge on the same snapshot");
        }

        /// 🧬️ Registered twin of [`assert_two_instances_converge`].
        pub async fn assert_two_registered_instances_converge<A, P, Manifest, Build>(channel: &str, manifest: Build, command_a: A::Command, command_b: A::Command, probe: impl Fn(&VcsArtifactApp<A>) -> P)
        where
            A: ArtifactApp + Default,
            P: PartialEq + std::fmt::Debug,
            Manifest: std::future::Future<Output = App>,
            Build: Fn() -> Manifest,
        {
            let (mut instance_a, mut instance_b) = paired_registered_apps::<A, Manifest, Build>(channel, manifest).await;
            instance_a.dispatch_typed(command_a, &meta("actor-a")).await.expect("a applies its edit");
            instance_b.dispatch_typed(command_b, &meta("actor-b")).await.expect("b applies its edit");
            instance_a.handle_action("commitCheckpoint", None, &meta("actor-a")).await.expect("pump a");
            instance_b.handle_action("commitCheckpoint", None, &meta("actor-b")).await.expect("pump b");
            assert_eq!(probe(&instance_a), probe(&instance_b), "both instances must converge on the same snapshot");
            close_registered_fixture_app(&mut instance_a);
            close_registered_fixture_app(&mut instance_b);
        }

        // 🪦️ `assert_graph_merge_preserves_referential_integrity` DELETED
        // (`26/08/16/MUTATION-OUTCOMES-MERGE-POLICIES-AND-FIRST-CLASS-CONFLICTS` M1): zero callers
        // repo-wide (confirmed via grep) — a generic testkit helper offered for app tests to probe
        // `(snapshot, Vec<..>)`-of-free-form-diagnostics-shaped reconcile results, but no app's own test suite ever
        // called it; the one real exercise of this exact scenario is
        // `🖥️host/🦀️component.rs`'s `concurrent_delete_and_wire_reconciles_without_a_dangling_edge`,
        // written directly against `OsWorkflowStore`/`reconcile_workflow_snapshot` rather than through
        // this helper. Dead code deleted rather than migrated to `Vec<protocol::MutationMessage>`.

        /// 🧪️ Applies `command` on a sender attached to a backbone, replays the resulting envelopes onto a
        /// fresh receiver twice, and asserts `probe` sees the same result both times — feeding the same operation
        /// twice must not double-apply.
        pub async fn assert_ingest_idempotent<A, P>(command: A::Command, probe: impl Fn(&VcsArtifactApp<A>) -> P)
        where
            A: ArtifactApp + Default,
            P: PartialEq + std::fmt::Debug,
        {
            let mut sender = new_app::<A>().await;
            let (near, mut far) = MemoryBackbone::pair("mem://testkit-idempotent", "mem://testkit-idempotent").await;
            sender.attach_backbone(store::Backbones::Memory(near)).await.expect("attach sender");
            sender.dispatch_typed(command, &meta("local")).await.expect("apply command");

            let mut envelopes = Vec::new();
            for message in far.receive().await.expect("receive") {
                if let BackboneMessage::Mutations { envelopes: operations } = message {
                    envelopes.extend(protocol::decode_envelopes(&operations).expect("decode envelopes"));
                }
            }
            let operations = protocol::encode_envelopes(&envelopes);

            let mut receiver = new_app::<A>().await;
            receiver.ingest_operations(&operations).await.expect("ingest once");
            let once = probe(&receiver);
            receiver.ingest_operations(&operations).await.expect("ingest twice");
            assert_eq!(probe(&receiver), once, "feeding the same operation twice must not double-apply");
        }

        /// 🧬️ Registered twin of [`assert_ingest_idempotent`].
        pub async fn assert_registered_ingest_idempotent<A, P, Manifest, Build>(manifest: Build, command: A::Command, probe: impl Fn(&VcsArtifactApp<A>) -> P)
        where
            A: ArtifactApp + Default,
            P: PartialEq + std::fmt::Debug,
            Manifest: std::future::Future<Output = App>,
            Build: Fn() -> Manifest,
        {
            let mut sender = new_registered_app::<A, _>(manifest()).await;
            let (near, mut far) = MemoryBackbone::pair("mem://testkit-idempotent", "mem://testkit-idempotent").await;
            sender.attach_backbone(store::Backbones::Memory(near)).await.expect("attach sender");
            sender.dispatch_typed(command, &meta("local")).await.expect("apply command");
            let mut envelopes = Vec::new();
            for message in far.receive().await.expect("receive") {
                if let BackboneMessage::Mutations { envelopes: operations } = message {
                    envelopes.extend(protocol::decode_envelopes(&operations).expect("decode envelopes"));
                }
            }
            let operations = protocol::encode_envelopes(&envelopes);
            let mut receiver = new_registered_app::<A, _>(manifest()).await;
            receiver.ingest_operations(&operations).await.expect("ingest once");
            let once = probe(&receiver);
            receiver.ingest_operations(&operations).await.expect("ingest twice");
            assert_eq!(probe(&receiver), once, "feeding the same operation twice must not double-apply");
            close_registered_fixture_app(&mut sender);
            close_registered_fixture_app(&mut receiver);
        }

        //#region 🧪️testkit
        /// 🔀️ Dispatches `command` and asserts it produced a `TransactionProposalDraft` instead of
        /// applying anything (contract §5.1) — the guest-side half of "propose instead of apply".
        /// Returns the draft so a test can inspect `local_ops`/`foreign`/`description`/`coalesce_key`.
        pub async fn assert_proposes_transaction<A: ArtifactApp>(app: &mut VcsArtifactApp<A>, command: A::Command) -> super::TransactionProposalDraft {
            let generation_before = app.store.generation();
            let edits_before = app.store.envelope().vcs.edits.len();
            app.dispatch_typed(command, &meta("local")).await.expect("dispatch a command whose mutations carry foreign steps");
            assert_eq!(app.store.generation(), generation_before, "a proposed transaction must not bump the document store's generation");
            assert_eq!(app.store.envelope().vcs.edits.len(), edits_before, "a proposed transaction must not add an Edit");
            app.take_pending_transaction_proposal().await.expect("dispatch_emit must stash a TransactionProposalDraft when foreign steps are present")
        }

        /// 🔀️ Scripts a whole pre-planned-form transaction against ONE in-process member without a
        /// host: prepares `ops` under `txn_id`/`label`/`origin`, asserts the prepare was accepted,
        /// commits, and asserts exactly one resulting `Edit` whose `group_id` is `txn_id` and whose
        /// every `MutationMeta.origin` is `origin`. Returns the committed edit id.
        pub async fn assert_transaction_commits_as_one_edit<A: ArtifactApp>(app: &mut VcsArtifactApp<A>, txn_id: &str, ops: Vec<A::Mutation>, label: &str, origin: protocol::MutationOrigin) -> String {
            let edits_before = app.store.envelope().vcs.edits.len();
            let mut prepared_ops: Vec<Vec<u8>> = Vec::with_capacity(ops.len());
            for op in ops.iter() {
                prepared_ops.push(::protocol::OpBinary::encode_op(op).expect("encode prepared op"));
            }
            let outcome = app.transaction_prepare(txn_id, "", &[], &prepared_ops, label, Some(origin.clone())).await;
            assert!(outcome.rejection.is_none(), "prepare unexpectedly rejected: {:?}", outcome.rejection.as_ref().map(|fault| &fault.message));
            let edit_id = app.transaction_commit(txn_id, &meta("local")).await.expect("commit prepared transaction");
            assert_eq!(app.store.envelope().vcs.edits.len(), edits_before + 1, "commit must produce exactly one new Edit");
            let edit = app.store.envelope().vcs.edits.last().expect("committed edit must exist");
            assert_eq!(edit.id, edit_id, "transaction_commit must return the tail edit's own id");
            assert!(!edit.mutation_meta.is_empty(), "the committed edit must carry at least one MutationMeta entry");
            for op_meta in &edit.mutation_meta {
                assert_eq!(op_meta.group_id.as_deref(), Some(txn_id), "every op in the committed edit must carry the transaction's group_id");
                assert_eq!(op_meta.origin, origin, "every op in the committed edit must carry the prepared origin");
            }
            edit_id
        }

        /// 🔀️ Prepares then rolls back a transaction, asserting the store's generation and edit
        /// count are completely untouched (contract §5.5: rollback discards pending state without
        /// ever having applied anything).
        pub async fn assert_transaction_rollback_leaves_state_untouched<A: ArtifactApp>(app: &mut VcsArtifactApp<A>, txn_id: &str, ops: Vec<A::Mutation>, label: &str) {
            let generation_before = app.store.generation();
            let edits_before = app.store.envelope().vcs.edits.len();
            let mut prepared_ops: Vec<Vec<u8>> = Vec::with_capacity(ops.len());
            for op in ops.iter() {
                prepared_ops.push(::protocol::OpBinary::encode_op(op).expect("encode prepared op"));
            }
            let outcome = app.transaction_prepare(txn_id, "", &[], &prepared_ops, label, Some(protocol::MutationOrigin::Owner)).await;
            assert!(outcome.rejection.is_none(), "prepare unexpectedly rejected");
            app.transaction_rollback(txn_id).await.expect("rollback the pending transaction");
            assert_eq!(app.store.generation(), generation_before, "rollback must not change the store generation");
            assert_eq!(app.store.envelope().vcs.edits.len(), edits_before, "rollback must not add any edit");
        }
        //#endregion 🧪️testkit

        //#region 🧪️testkit
        //#endregion 🧪️testkit

        //#region 👁️✏️SurfaceTestkit
        // 🎫️ Ticket 26/08/16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET contract §2.5 — lane 0-F. New
        // subregion, appended after the peer `🧪️testkit` subregion above without touching it.
        use super::{declarations, ArtifactEditor, ArtifactViewer, ViewerApp};

        /// 👁️ Contract §2.5 helper 1/3 — WITH TEETH: dispatches a real `V::Command` through the full
        /// `VcsArtifactApp<ViewerApp<V>>` runtime path (the same one `PluginBuilder::viewer::<V>`
        /// wires up) and asserts neither the document store nor the draft store advanced. `ViewEmit`
        /// (contract §2.2) already makes an artifact/draft mutation unnameable at the type level; this
        /// additionally proves the runtime adapter (`ViewerApp<V>::handle`) never smuggles one past
        /// that guarantee. `V::Command: Default` is the minimal extra bound needed to synthesize a
        /// representative command with no caller-supplied value — `ArtifactViewer` itself declares
        /// none, since a viewer's command grammar is author-defined; a no-op-only command (the norm
        /// for a first-pass viewer, contract §2.2) derives `Default` for free.
        pub async fn assert_viewer_never_mutates<V: ArtifactViewer>()
        where
            V::Command: Default,
        {
            let mut app = new_viewer::<V>().await;
            let store_generation_before = app.store.generation();
            let store_edits_before = app.store.envelope().vcs.edits.len();
            let draft_generation_before = app.draft_store.generation();
            let draft_edits_before = app.draft_store.envelope().vcs.edits.len();
            app.dispatch_typed(V::Command::default(), &meta("local")).await.expect("a viewer command must dispatch without error");
            assert_eq!(app.store.generation(), store_generation_before, "a viewer must never bump the document store's generation");
            assert_eq!(app.store.envelope().vcs.edits.len(), store_edits_before, "a viewer must never add a document Edit");
            assert_eq!(app.draft_store.generation(), draft_generation_before, "a viewer must never bump the draft store's generation");
            assert_eq!(app.draft_store.envelope().vcs.edits.len(), draft_edits_before, "a viewer must never add a draft Edit");
        }

        /// ✏️👁️ Contract §2.5 helper 2/3 — an editor and its viewer over the same subset must resolve
        /// to one `Dialect` coordinate, or `surface_app_id` would mint two different canonical ids
        /// (`…#editor` / `…#viewer`) for what the contract treats as one subset's two surfaces.
        pub async fn assert_editor_and_viewer_share_dialect<E: ArtifactEditor, V: ArtifactViewer>() {
            assert_eq!(E::DIALECT, V::DIALECT, "an editor and its viewer over the same subset must share one Dialect coordinate");
        }

        /// 👁️ Contract §2.5 helper 3/3 — the viewer twin of `new_app::<A: ArtifactApp>()`. `ViewerApp<V>`
        /// already satisfies the runtime `ArtifactApp` bound (the SDK adapter, contract §2.1), so this
        /// is a thin rename over the existing generic harness rather than new machinery.
        pub async fn new_viewer<V: ArtifactViewer>() -> VcsArtifactApp<ViewerApp<V>> {
            new_app::<ViewerApp<V>>().await
        }

        //#endregion 👁️✏️SurfaceTestkit

        //#region 🔖️DeclarationTestkit
        // 🌳️ Ticket 26/08/17/CLEAN-ARTIFACT-STANDARD-SUBSET-MECHANISM W1-C Task 4 — laws for the new
        // declaration tree (`super::declarations`). Every law commits through the REAL
        // `PluginBuilder::declare_artifact`/`try_build` path (or, for the pure id-derivation law, no
        // registration at all) rather than reaching into `declarations::commit_artifact_declarations`
        // directly, so a passing law is proof the whole public surface works end to end.
        /// 🌳️ Builds a plugin from `declaration` and asserts every subset ends up registered in the
        /// schema registry, the io registry (when it declares any `IoEntry` rows), and the app router
        /// (manifest apps) — "nothing is silently dropped" (Task 4, law 1/3).
        pub async fn assert_declaration_tree_registers_all<PA: super::PluginApp>(plugin_id: &str, declaration: declarations::ArtifactDeclaration<PA>) {
            let expected_schema_ids: Vec<&'static str> = declaration.standards.iter().flat_map(|standard| standard.subsets.iter().map(|subset| subset.schema.descriptor.id)).collect();
            let mut expected_io_pairs: Vec<(String, String)> = Vec::new();
            for entry in declaration.standards.iter().flat_map(|standard| standard.subsets.iter()).flat_map(|subset| subset.io.entries.iter()) {
                expected_io_pairs.push((semio_framework::io_schema::ArtifactDialect::from(entry.from).to_coordinate(), semio_framework::io_schema::ArtifactDialect::from(entry.into).to_coordinate()));
            }
            let expected_surface_ids: Vec<String> = declaration.standards.iter().flat_map(|standard| standard.subsets.iter()).flat_map(|subset| [subset.editor.definition.id.clone(), subset.viewer.definition.id.clone()]).collect();

            let plugin = super::Plugin::builder(plugin_id).label(plugin_id).version("0.0.1").declare_artifact(declaration).try_build().expect("a well-formed declaration tree must register");

            for id in &expected_schema_ids {
                assert!(::semio_framework_schema::artifact_schema_descriptor_registered(id), "schema descriptor {id:?} must be registered");
            }
            let live_io_entries = semio_framework::io::io_mechanism::io_entries();
            for (from, into) in &expected_io_pairs {
                let mut found = false;
                for entry in live_io_entries.iter() {
                    if &entry.from.to_coordinate() == from && &entry.into.to_coordinate() == into {
                        found = true;
                        break;
                    }
                }
                assert!(found, "io entry {from} -> {into} must be registered");
            }
            let live_app_ids: Vec<&str> = plugin.manifest.apps.iter().map(|app| app.id.as_str()).collect();
            for id in &expected_surface_ids {
                assert!(live_app_ids.contains(&id.as_str()), "surface {id:?} must be registered on the app router");
            }
        }

        /// 🌳️ `invalid` must fail preflight by construction (e.g. two subsets whose schema
        /// descriptors share an id with different content) — asserts the schema AND io registries are
        /// byte-for-byte unchanged after the rejection: a preflight-failing declaration leaves ZERO
        /// rows behind (Task 4, law 2/3).
        pub async fn assert_declaration_registration_is_atomic<PA: super::PluginApp>(plugin_id: &str, invalid: declarations::ArtifactDeclaration<PA>) {
            let schema_count_before = ::semio_framework_schema::with_artifact_schema_registry(|registry| registry.len());
            let io_count_before = semio_framework::io::io_mechanism::io_entries().len();
            let result = super::Plugin::builder(plugin_id).label(plugin_id).version("0.0.1").declare_artifact(invalid).try_build();
            assert!(result.is_err(), "a declaration that fails preflight must not build a plugin");
            assert_eq!(::semio_framework_schema::with_artifact_schema_registry(|registry| registry.len()), schema_count_before, "schema registry must be unchanged after a rejected declaration");
            assert_eq!(semio_framework::io::io_mechanism::io_entries().len(), io_count_before, "io registry must be unchanged after a rejected declaration");
        }

        /// 🌳️ Every subset's editor/viewer surface id must equal `surface_app_id(&dialect, role)` —
        /// pure, no registration (Task 4, law 3/3).
        pub async fn assert_subset_declaration_ids_are_derived<PA: super::PluginApp>(declaration: &declarations::ArtifactDeclaration<PA>) {
            for standard in &declaration.standards {
                for subset in &standard.subsets {
                    let dialect: semio_framework::ArtifactDialect = subset.dialect.into();
                    assert_eq!(subset.editor.definition.id, semio_framework::surface_app_id(&dialect, semio_framework::AppRole::Editor), "editor surface id must be derived via surface_app_id");
                    assert_eq!(subset.viewer.definition.id, semio_framework::surface_app_id(&dialect, semio_framework::AppRole::Viewer), "viewer surface id must be derived via surface_app_id");
                }
            }
        }
        //#endregion 🔖️DeclarationTestkit
    }
    //#endregion 🔖️Testkit

