    //#endregion 🔖️WindowKits

    //#region 🔖️Surfaces
    use semio_framework::{surface_app_id, AppRole};

    /// 🎭️ Authoring traits for artifact surfaces split by mutation capability (ticket
    /// 26/08/16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET contract §2.1/§2.2/§2.4). `ArtifactEditor`
    /// and `ArtifactViewer` replace `ArtifactApp` as the trait an app AUTHOR implements; the runtime
    /// `ArtifactApp` trait above is unchanged and is satisfied by the `EditorApp`/`ViewerApp` adapters
    /// below through pure delegation — nothing here alters runtime dispatch.

    //#region 🔖️ArtifactEditor
    /// 👁️✏️ Authoring trait for a mutation-capable surface — a structural copy of `ArtifactApp`'s
    /// members (contract §2.1) plus `ROLE`/`DIALECT`; `APP_ID` is intentionally absent, the runtime id
    /// being derived from `DIALECT`+`ROLE` via `surface_app_id` (contract §7.4) instead of hand-written.
    /// `EditorApp<E>` below is the sole `ArtifactApp` implementor for any `E: ArtifactEditor`.
    pub trait ArtifactEditor: Default + Send + 'static {
        /// 🎭️ Always `Editor` in practice — defaulted so implementors never restate it.
        const ROLE: AppRole = AppRole::Editor;
        const DIALECT: Dialect;
        const REQUIRES_DOCUMENT_STORE_PUBLICATION_AUTHORITY: bool = false;
        /// @emoji 📜️ Stable document schema id — prefer this over `document_schema(&self)`.
        const DOCUMENT_SCHEMA: &'static str;
        type Snapshot: Clone + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type Mutation: ::protocol::Mutation<Self::Snapshot> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Config: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ConfigRecord + ArtifactPack + 'static;
        type ConfigMutation: ::protocol::Mutation<Self::Config> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Draft: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type DraftMutation: ::protocol::Mutation<Self::Draft> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Presence: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type PresenceMutation: ::protocol::Mutation<Self::Presence> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Transient: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type TransientMutation: ::protocol::Mutation<Self::Transient> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Command: ::protocol::OpBinary + Send + Sync + 'static;

        /// 📜️ Exact owner-local bounded reducer proofs forwarded by `EditorApp<Self>`.
        fn bounded_first_step_tool_proofs() -> Vec<ArtifactBoundedFirstStepProof> {
            Vec::new()
        }

        fn mounted_job_maintenance_step(_instance_id: u32, _maximum_items: usize, _maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            Ok(PluginCloseStep::Complete)
        }

        fn mounted_job_close_step(_instance_id: u32, _maximum_items: usize, _maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            Ok(PluginCloseStep::Complete)
        }

        fn mounted_jobs_terminal_is_empty(_instance_id: u32) -> bool {
            true
        }

        fn mounted_job_prepare_snapshot_read(_operation: AppRenderOperationContext, _snapshot: &Self::Snapshot) -> bool {
            false
        }

        /// 🧩️ Author-owned forwarding seam for factories whose concrete runtime owner is the
        /// framework's `EditorApp<Self>` adapter.
        fn register_tool_job_factories(_registry: &mut ArtifactToolFactoryRegistry<'_, EditorApp<Self>>) -> Result<(), Fault> {
            Ok(())
        }

        fn build_instance_operation_owner() -> Box<dyn ArtifactInstanceOperationOwner> {
            Box::new(EmptyArtifactInstanceOperationOwner)
        }

        /// 🏗️ Author-owned payload builder paired with `register_tool_job_factories`.
        fn build_tool_job(_request: ArtifactOwnedToolJobRequest<EditorApp<Self>>) -> Result<Option<semio_framework::ToolOperationSpec>, Fault> {
            Ok(None)
        }

        /// 🧭️ Author-owned reserved-route producer paired with an exact registered factory.
        fn build_reserved_tool_job(_request: ArtifactReservedToolJobRequest<EditorApp<Self>>) -> Result<Option<ArtifactReservedToolJob>, Fault> {
            Ok(None)
        }

        /// 🎞️ Author-owned resumable media-output producer for `EditorApp<Self>`.
        fn build_media_export_job(_request: ArtifactMediaExportJobRequest<EditorApp<Self>>) -> Result<Option<ArtifactReservedToolJob>, Fault> {
            Ok(None)
        }

        fn build_snapshot_disposer() -> Option<Box<dyn ArtifactSnapshotDisposer<Self::Snapshot>>> {
            None
        }

        fn build_envelope_decode_owner_bundle() -> Option<store::ArtifactEnvelopeDecodeOwnerBundle<Self::Snapshot, Self::Mutation>> {
            None
        }

        fn build_document_store_owners() -> Option<store::MemberStoreOwners<Self::Snapshot, Self::Mutation>> {
            None
        }

        fn build_config_store_owners() -> Option<store::MemberStoreOwners<Self::Config, Self::ConfigMutation>> {
            None
        }

        /// 📝️ Grants exact draft retirement ownership to this editor adapter.
        fn build_draft_store_owners() -> Option<store::MemberStoreOwners<Self::Draft, Self::DraftMutation>> {
            None
        }

        /// 📬️ Grants retained one-item document preparation to this editor adapter.
        fn build_artifact_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactStoreOneItemPreparationFactory<Self::Snapshot, Self::Mutation>>> {
            None
        }

        /// 📬️ Grants retained one-item config preparation to this editor adapter.
        fn build_config_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactStoreOneItemPreparationFactory<Self::Config, Self::ConfigMutation>>> {
            None
        }

        /// 📬️ Grants retained one-item draft preparation to this editor adapter.
        fn build_draft_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactStoreOneItemPreparationFactory<Self::Draft, Self::DraftMutation>>> {
            None
        }

        /// 📬️ Grants retained shared-live presence preparation to this editor adapter.
        fn build_presence_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactEphemeralOneItemPreparationFactory<Self::Presence, Self::PresenceMutation>>> {
            None
        }

        /// 📬️ Grants retained local-live transient preparation to this editor adapter.
        fn build_transient_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactEphemeralOneItemPreparationFactory<Self::Transient, Self::TransientMutation>>> {
            None
        }

        /// 🧹️ Grants bounded displaced-presence-root retirement to this editor adapter.
        fn build_presence_local_root_retirement_factory() -> Option<std::sync::Arc<dyn store::SnapshotRetirementFactory<Self::Presence>>> {
            None
        }

        /// 👥️ Grants exact typed retirement for peer presence snapshots to this editor adapter.
        fn build_presence_peer_retirement_factory() -> Option<std::sync::Arc<dyn store::SnapshotRetirementFactory<Self::Presence>>> {
            None
        }

        /// 🧹️ Grants bounded displaced-transient-root retirement to this editor adapter.
        fn build_transient_local_root_retirement_factory() -> Option<std::sync::Arc<dyn store::SnapshotRetirementFactory<Self::Transient>>> {
            None
        }

        fn build_document_store_initialization_job(
            envelope: ArtifactEnvelope<Self::Snapshot, Self::Mutation>,
            _operation: semio_framework_job::OperationId,
            _generation: semio_framework_job::Generation,
        ) -> Result<ArtifactStoreInitializationJob<Self::Snapshot, Self::Mutation>, ArtifactEnvelope<Self::Snapshot, Self::Mutation>> {
            Err(envelope)
        }

        fn validate_document_store_publication(_operation: semio_framework_job::OperationId, _generation: semio_framework_job::Generation, _live_generation: semio_framework_job::Generation) -> Result<(), Fault> {
            if Self::REQUIRES_DOCUMENT_STORE_PUBLICATION_AUTHORITY {
                Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.publication-authority-missing"), "registered editor did not supply atomic publication authority"))
            } else {
                Ok(())
            }
        }

        fn build_document_store_disposer() -> Option<Box<dyn ArtifactOwnedDisposer<ArtifactStore<Self::Snapshot, Self::Mutation>>>> {
            None
        }

        fn build_config_store_disposer() -> Option<Box<dyn ArtifactOwnedDisposer<ConfigStore<Self::Config, Self::ConfigMutation>>>> {
            None
        }

        fn build_draft_store_disposer() -> Option<Box<dyn ArtifactOwnedDisposer<store::DraftStore<Self::Draft, Self::DraftMutation>>>> {
            None
        }

        fn build_presence_store_disposer() -> Option<Box<dyn ArtifactOwnedDisposer<store::PresenceStore<Self::Presence, Self::PresenceMutation>>>> {
            None
        }

        fn build_transient_store_disposer() -> Option<Box<dyn ArtifactOwnedDisposer<store::TransientStore<Self::Transient, Self::TransientMutation>>>> {
            None
        }

        /// 👥️🫧️ The two EPHEMERAL lanes this command touches. Returns a plain tuple rather than
        /// `EphemeralEmit<Self>` — that struct is bound to the RUNTIME `ArtifactApp` trait, which
        /// `Self` here does not implement; `EditorApp<E>::ephemeral` wraps this tuple into a real
        /// `EphemeralEmit` at the adapter boundary, where the bound is satisfied.
        fn ephemeral(
            _command: &Self::Command,
            _doc: &ArtifactView<'_, Self::Snapshot>,
            _cfg: &ConfigView<'_, Self::Config>,
            _presence: &PresenceView<'_, Self::Presence>,
            _transient: &TransientView<'_, Self::Transient>,
        ) -> (Vec<Self::PresenceMutation>, Vec<Self::TransientMutation>) {
            (Vec::new(), Vec::new())
        }
        fn config_schema() -> &'static str {
            "config.empty"
        }
        fn initial_snapshot() -> Self::Snapshot;
        fn initial_config() -> Self::Config {
            Self::Config::default()
        }
        /// 🧭️ Resolves a host-owned control-plane action to one configuration mutation.
        /// `EditorApp<E>` forwards this exact owner hook to the runtime adapter.
        fn host_configuration_mutation(_action: &str, _args: Option<&Value>) -> Result<Option<Self::ConfigMutation>, Fault> {
            Ok(None)
        }
        fn initial_draft() -> Self::Draft {
            Self::Draft::default()
        }
        /// @emoji 🧩️ The pure heart of an editor — identical shape to `ArtifactApp::handle`.
        fn handle(
            command: &Self::Command,
            doc: &ArtifactView<'_, Self::Snapshot>,
            cfg: &ConfigView<'_, Self::Config>,
            interaction: &InteractionView<'_>,
            draft: &DraftView<'_, Self::Draft>,
            engines: &EngineHandles,
        ) -> Result<Emit<Self::Mutation, Self::ConfigMutation, Self::DraftMutation>, Fault>;
        fn command_id(_command: &Self::Command) -> &'static str {
            "typed-command"
        }
        fn command_from_action(action: &str, _args: Option<&Value>) -> Result<Self::Command, Fault> {
            Err(Fault::new(
                FaultOrigin::App,
                FaultCode::new("app.command.unsupported"),
                format!("action '{action}' is not a framework-reserved action (history/clipboard/revert/filter/noteShellCommand) — app actions are dispatched exclusively through the typed command channel now (see `dispatch_typed_command`)"),
            ))
        }
        /// 🎯️ M1: `ArtifactApp::command_from_intent`'s sibling default for a hand-authored
        /// `ArtifactEditor` — same version-mismatch Fault, same `merge_ui_values` bridge to
        /// `Self::command_from_action`. `EditorApp<E>`'s `ArtifactApp` impl delegates its own
        /// `command_from_intent` here, so overriding it on `E` actually takes effect.
        async fn command_from_intent(intent: &UiIntent) -> Result<Self::Command, Fault> {
            if intent.action.version != 1 {
                return Err(Fault::new(
                    FaultOrigin::App,
                    FaultCode::new("app.intent.version-mismatch"),
                    format!(
                        "intent action '{}' targets version {} but the default intent bridge only resolves version-1 actions (see `ArtifactEditor::command_from_intent`'s own doc) — override it for a versioned contract",
                        intent.action.name, intent.action.version
                    ),
                ));
            }
            let merged = merge_ui_values(intent.args.as_ref(), intent.input.as_ref()).await?;
            Self::command_from_action(&intent.action.name, merged.as_ref())
        }
        fn config_spec() -> ConfigSpec {
            ConfigSpec::default()
        }
        fn clipboard_media_type() -> Option<MediaType> {
            None
        }
        fn clipboard_accepts() -> Vec<MediaType> {
            Self::clipboard_media_type().into_iter().collect()
        }
        fn copy_fragment(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>, _interaction: &InteractionView<'_>) -> Result<ClipboardFragment, ClipboardError> {
            Err(ClipboardError::EmptySelection)
        }
        fn cut_operations(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>, _interaction: &InteractionView<'_>) -> Vec<Self::Mutation> {
            Vec::new()
        }
        fn interaction_topology(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> protocol::InteractionTopology {
            protocol::InteractionTopology::default()
        }
        fn paste_operations(_doc: &ArtifactView<'_, Self::Snapshot>, _fragment: &ClipboardFragment, _placement: &PastePlacement) -> Result<Vec<Self::Mutation>, ClipboardError> {
            Ok(Vec::new())
        }
        fn pending_effects(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> Vec<Effect> {
            Vec::new()
        }
        fn render(body_key: &str, doc: &ArtifactView<'_, Self::Snapshot>, cfg: &ConfigView<'_, Self::Config>) -> UiAssemblyResult<ComponentTree>;
        /// 🎭️ Renders against the same instance-retained operation owner used by typed jobs.
        fn render_with_instance_operation_owner(owner: &ArtifactInstanceOperationOwnerHandle, body_key: &str, doc: &ArtifactView<'_, Self::Snapshot>, cfg: &ConfigView<'_, Self::Config>) -> UiAssemblyResult<ComponentTree> {
            let _ = owner;
            Self::render(body_key, doc, cfg)
        }
        /// 🧮️ Renders from the same immutable transient snapshot retained by app-owned jobs.
        ///
        /// 🕹️ `interaction` reads the framework-owned interaction mechanism (hover + selection) so a
        /// window can paint its own hovered/selected state instead of ever storing it again itself —
        /// see `26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM`.
        fn render_with_request_context(
            owner: &ArtifactInstanceOperationOwnerHandle,
            body_key: &str,
            doc: &ArtifactView<'_, Self::Snapshot>,
            cfg: &ConfigView<'_, Self::Config>,
            transient: &TransientView<'_, Self::Transient>,
            interaction: &InteractionView<'_>,
        ) -> UiAssemblyResult<ComponentTree> {
            let _ = (transient, interaction);
            Self::render_with_instance_operation_owner(owner, body_key, doc, cfg)
        }
        fn window_engagements(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> HashMap<String, WindowEngagement> {
            HashMap::new()
        }
        fn window_measures(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> HashMap<String, Vec<WindowMeasure>> {
            HashMap::new()
        }
        fn tool_measures(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> HashMap<String, Vec<WindowMeasure>> {
            HashMap::new()
        }
        fn context_menu(_request: &ContextMenuRequest, _doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>, _registry: &AppActionRegistry) -> Vec<ContextMenuItemSpec> {
            Vec::new()
        }
        fn genesis() -> Vec<Self::Mutation> {
            Vec::new()
        }
        fn app_schema() -> Option<::semio_framework_schema::AppSchemaDescriptor> {
            None
        }
        fn io() -> Option<AppIo> {
            None
        }
        async fn media_ports() -> Vec<MediaPortSpec> {
            match Self::io() {
                Some(io) => io.all_ports().await,
                None => Vec::new(),
            }
        }
        /// 🌀️ `io-async-signatures`: async signature, behaviourally unchanged body.
        fn export_media(port: &str, doc: &ArtifactView<'_, Self::Snapshot>) -> Result<Media, MediaError> {
            if port != "document:out" {
                return Err(MediaError::NotImplemented);
            }
            let media_type = Self::io().map(|io| io.document_media_type).unwrap_or(MediaType { class: MediaClass::Data, form: MediaForm::Value });
            let bytes = doc.snapshot.encode_pack();
            Ok(Media { media_type, payload: MediaPayload::Structured { schema: Self::DOCUMENT_SCHEMA.to_string(), json: store::pack_rt::pack_value_to_base64(&bytes) } })
        }
        fn export_media_with_request_context(port: &str, doc: &ArtifactView<'_, Self::Snapshot>, transient: &TransientView<'_, Self::Transient>) -> Result<Media, MediaError> {
            let _ = transient;
            Self::export_media(port, doc)
        }
        fn whole_document_operation(_snapshot: Self::Snapshot) -> Option<Self::Mutation> {
            None
        }
        fn import_media(port: &str, media: &Media, _doc: &ArtifactView<'_, Self::Snapshot>) -> Result<Emit<Self::Mutation, Self::ConfigMutation, Self::DraftMutation>, MediaError> {
            if port != "document:in" {
                return Err(MediaError::NotImplemented);
            }
            let MediaPayload::Structured { json, .. } = &media.payload else {
                return Err(MediaError::Payload(port.to_string(), "default document:in importer only accepts a Structured (base64 pack) payload".into()));
            };
            let bytes = store::pack_rt::pack_value_from_base64(json).map_err(|error| MediaError::Payload(port.to_string(), error.to_string()))?;
            let snapshot = <Self::Snapshot as ArtifactPack>::decode_pack(&bytes).map_err(|error| MediaError::Payload(port.to_string(), error.to_string()))?;
            match Self::whole_document_operation(snapshot) {
                Some(operation) => Ok(Emit::mutations(vec![operation])),
                None => Err(MediaError::NotImplemented),
            }
        }
        /// 🌀️ `io-async-signatures`: async signature (delegates to the now-async `export_media`).
        fn media_fingerprint(port: &str, doc: &ArtifactView<'_, Self::Snapshot>) -> Result<MediaFingerprint, MediaError> {
            match Self::export_media(port, doc) {
                Ok(media) => Ok(MediaFingerprint::of(&media)),
                Err(error) => Err(error),
            }
        }
    }
    //#endregion 🔖️ArtifactEditor

    //#region 🔖️ArtifactViewer
    /// 👁️ Authoring trait for a read-only surface (contract §2.2) — the mutation-incapable twin of
    /// `ArtifactEditor`. `Mutation` stays decode-only (the store's op log must still decode past
    /// edits an `ArtifactEditor` made) but `handle` returns `ViewEmit`, which cannot structurally
    /// carry an artifact or draft mutation. `ViewerApp<V>` below is the sole `ArtifactApp` implementor.
    pub trait ArtifactViewer: Default + Send + 'static {
        /// 🎭️ Always `Viewer` in practice — defaulted so implementors never restate it.
        const ROLE: AppRole = AppRole::Viewer;
        const DIALECT: Dialect;
        const DOCUMENT_SCHEMA: &'static str;
        type Snapshot: Clone + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        /// 📜️ Decode-only — never constructed by `handle`, but the store's op log must still decode
        /// past edits made by an `ArtifactEditor` sharing this dialect.
        type Mutation: ::protocol::Mutation<Self::Snapshot> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Config: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ConfigRecord + ArtifactPack + 'static;
        type ConfigMutation: ::protocol::Mutation<Self::Config> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Presence: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type PresenceMutation: ::protocol::Mutation<Self::Presence> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Transient: Clone + Default + PartialEq + Serialize + DeserializeOwned + Send + Sync + store::ArtifactDsl + ArtifactPack + 'static;
        type TransientMutation: ::protocol::Mutation<Self::Transient> + PartialEq + Send + ::protocol::OpText + ::protocol::OpBinary + 'static;
        type Command: ::protocol::OpBinary + Send + Sync + 'static;

        fn mounted_job_maintenance_step(_instance_id: u32, _maximum_items: usize, _maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            Ok(PluginCloseStep::Complete)
        }

        fn mounted_job_close_step(_instance_id: u32, _maximum_items: usize, _maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            Ok(PluginCloseStep::Complete)
        }

        fn mounted_jobs_terminal_is_empty(_instance_id: u32) -> bool {
            true
        }

        fn mounted_job_prepare_snapshot_read(_operation: AppRenderOperationContext, _snapshot: &Self::Snapshot) -> bool {
            false
        }

        /// 📬️ Grants retained one-item config preparation to this viewer adapter.
        fn build_config_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactStoreOneItemPreparationFactory<Self::Config, Self::ConfigMutation>>> {
            None
        }

        /// 📬️ Grants retained shared-live presence preparation to this viewer adapter.
        fn build_presence_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactEphemeralOneItemPreparationFactory<Self::Presence, Self::PresenceMutation>>> {
            None
        }

        /// 📬️ Grants retained local-live transient preparation to this viewer adapter.
        fn build_transient_store_one_item_preparation_factory() -> Option<std::sync::Arc<dyn store::ArtifactEphemeralOneItemPreparationFactory<Self::Transient, Self::TransientMutation>>> {
            None
        }

        /// 🧹️ Grants bounded displaced-presence-root retirement to this viewer adapter.
        fn build_presence_local_root_retirement_factory() -> Option<std::sync::Arc<dyn store::SnapshotRetirementFactory<Self::Presence>>> {
            None
        }

        /// 🧹️ Grants bounded displaced-transient-root retirement to this viewer adapter.
        fn build_transient_local_root_retirement_factory() -> Option<std::sync::Arc<dyn store::SnapshotRetirementFactory<Self::Transient>>> {
            None
        }

        /// 👥️🫧️ See `ArtifactEditor::ephemeral` for why this returns a tuple, not `EphemeralEmit<Self>`.
        fn ephemeral(
            _command: &Self::Command,
            _doc: &ArtifactView<'_, Self::Snapshot>,
            _cfg: &ConfigView<'_, Self::Config>,
            _presence: &PresenceView<'_, Self::Presence>,
            _transient: &TransientView<'_, Self::Transient>,
        ) -> (Vec<Self::PresenceMutation>, Vec<Self::TransientMutation>) {
            (Vec::new(), Vec::new())
        }
        fn config_schema() -> &'static str {
            "config.empty"
        }
        fn initial_snapshot() -> Self::Snapshot;
        fn initial_config() -> Self::Config {
            Self::Config::default()
        }
        /// 👁️ The pure heart of a viewer — same shape as `ArtifactEditor::handle` minus `draft` (a
        /// viewer never has a draft lane), returning `ViewEmit` instead of `Emit`: structurally
        /// incapable of an artifact or draft mutation (contract §2.2).
        fn handle(command: &Self::Command, doc: &ArtifactView<'_, Self::Snapshot>, cfg: &ConfigView<'_, Self::Config>, interaction: &InteractionView<'_>, engines: &EngineHandles) -> Result<ViewEmit<Self::ConfigMutation>, Fault>;
        fn command_id(_command: &Self::Command) -> &'static str {
            "typed-command"
        }
        fn command_from_action(action: &str, _args: Option<&Value>) -> Result<Self::Command, Fault> {
            Err(Fault::new(
                FaultOrigin::App,
                FaultCode::new("app.command.unsupported"),
                format!("action '{action}' is not a framework-reserved action (history/clipboard/revert/filter/noteShellCommand) — app actions are dispatched exclusively through the typed command channel now (see `dispatch_typed_command`)"),
            ))
        }
        fn config_spec() -> ConfigSpec {
            ConfigSpec::default()
        }
        fn interaction_topology(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> protocol::InteractionTopology {
            protocol::InteractionTopology::default()
        }
        fn render(body_key: &str, doc: &ArtifactView<'_, Self::Snapshot>, cfg: &ConfigView<'_, Self::Config>) -> UiAssemblyResult<ComponentTree>;
        /// 🕹️ `interaction` reads the framework-owned interaction mechanism (hover + selection) so a
        /// window can paint its own hovered/selected state instead of ever storing it again itself —
        /// see `26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM`.
        fn render_with_request_context(
            _owner: &ArtifactInstanceOperationOwnerHandle,
            body_key: &str,
            doc: &ArtifactView<'_, Self::Snapshot>,
            cfg: &ConfigView<'_, Self::Config>,
            transient: &TransientView<'_, Self::Transient>,
            interaction: &InteractionView<'_>,
        ) -> UiAssemblyResult<ComponentTree> {
            let _ = (transient, interaction);
            Self::render(body_key, doc, cfg)
        }
        fn pending_effects(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> Vec<Effect> {
            Vec::new()
        }
        fn window_engagements(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> HashMap<String, WindowEngagement> {
            HashMap::new()
        }
        fn window_measures(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> HashMap<String, Vec<WindowMeasure>> {
            HashMap::new()
        }
        fn tool_measures(_doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>) -> HashMap<String, Vec<WindowMeasure>> {
            HashMap::new()
        }
        fn context_menu(_request: &ContextMenuRequest, _doc: &ArtifactView<'_, Self::Snapshot>, _cfg: &ConfigView<'_, Self::Config>, _registry: &AppActionRegistry) -> Vec<ContextMenuItemSpec> {
            Vec::new()
        }
        fn app_schema() -> Option<::semio_framework_schema::AppSchemaDescriptor> {
            None
        }
        fn io() -> Option<AppIo> {
            None
        }
        async fn media_ports() -> Vec<MediaPortSpec> {
            match Self::io() {
                Some(io) => io.all_ports().await,
                None => Vec::new(),
            }
        }
        /// 🌀️ `io-async-signatures`: async signature, behaviourally unchanged body.
        fn export_media(port: &str, doc: &ArtifactView<'_, Self::Snapshot>) -> Result<Media, MediaError> {
            if port != "document:out" {
                return Err(MediaError::NotImplemented);
            }
            let media_type = Self::io().map(|io| io.document_media_type).unwrap_or(MediaType { class: MediaClass::Data, form: MediaForm::Value });
            let bytes = doc.snapshot.encode_pack();
            Ok(Media { media_type, payload: MediaPayload::Structured { schema: Self::DOCUMENT_SCHEMA.to_string(), json: store::pack_rt::pack_value_to_base64(&bytes) } })
        }
        fn export_media_with_request_context(port: &str, doc: &ArtifactView<'_, Self::Snapshot>, transient: &TransientView<'_, Self::Transient>) -> Result<Media, MediaError> {
            let _ = transient;
            Self::export_media(port, doc)
        }
        /// 🌀️ `io-async-signatures`: async signature (delegates to the now-async `export_media`).
        fn media_fingerprint(port: &str, doc: &ArtifactView<'_, Self::Snapshot>) -> Result<MediaFingerprint, MediaError> {
            match Self::export_media(port, doc) {
                Ok(media) => Ok(MediaFingerprint::of(&media)),
                Err(error) => Err(error),
            }
        }
    }
    //#endregion 🔖️ArtifactViewer

    //#region 🔖️ViewEmit
    /// 👁️ What a viewer may emit — structurally cannot carry an artifact or draft mutation (contract
    /// §2.2): the read-only guarantee is a type property, not a runtime check.
    pub struct ViewEmit<ConfigMutation> {
        pub config_mutations: Vec<ConfigMutation>,
        pub effects: Vec<Effect>,
        pub ui_dirty: semio_framework::kernel::UiDirtyScope,
    }

    impl<ConfigMutation> Default for ViewEmit<ConfigMutation> {
        fn default() -> Self {
            Self { config_mutations: Vec::new(), effects: Vec::new(), ui_dirty: semio_framework::kernel::UiDirtyScope::default() }
        }
    }

    impl<ConfigMutation> ViewEmit<ConfigMutation> {
        pub fn new() -> Self {
            Self::default()
        }
        /// 🧮️ A config-operation emission carrying `config_mutations` and nothing else.
        pub fn config(config_mutations: Vec<ConfigMutation>) -> Self {
            Self { config_mutations, ..Default::default() }
        }
        /// 🐚️ A single host effect and no config operations.
        pub fn effect(effect: Effect) -> Self {
            Self { effects: vec![effect], ..Default::default() }
        }
        /// 🐢️ Narrows which rendered UI sections this emission invalidates.
        pub fn dirty(ui_dirty: semio_framework::kernel::UiDirtyScope) -> Self {
            Self { ui_dirty, ..Default::default() }
        }
    }
    //#endregion 🔖️ViewEmit

    //#region 🔖️EditorApp
    /// 🗄️✏️ Adapter binding an `ArtifactEditor` author into the runtime `ArtifactApp` contract
    /// (contract §2.1) — pure delegation, `E` supplies every behavior. `APP_ID` is a fixed placeholder
    /// (see `id` field doc): the runtime trait's `APP_ID` must be a `&'static str` const, but the real
    /// derived id (`surface_app_id`) is only knowable at runtime, so the `Viewer`/`Editor` builders
    /// below set `AppDefinition.id` directly rather than reading this const.
    pub struct EditorApp<E: ArtifactEditor> {
        /// 🪪️ The real derived surface id, computed once in `Default::default()`. NOT `Self::APP_ID`
        /// (see struct doc) — exposed via `surface_id()` and `instance_id()` for `VcsArtifactApp`'s
        /// internal usages (its document/config/draft/interaction envelope ids, ownership-check
        /// error strings).
        id: String,
        _editor: std::marker::PhantomData<E>,
    }

    impl<E: ArtifactEditor> Default for EditorApp<E> {
        fn default() -> Self {
            Self { id: surface_app_id(&E::DIALECT.into(), E::ROLE), _editor: std::marker::PhantomData }
        }
    }

    impl<E: ArtifactEditor> EditorApp<E> {
        /// 🪪️ The real derived surface id — see struct doc.
        pub async fn surface_id(&self) -> &str {
            &self.id
        }
    }

